package com.hbm.client.oilfracking;
import com.hbm.client.gui.LegacyContainerScreen;import com.hbm.fluid.FluidTank;import com.hbm.item.fluid.client.FluidInfo;import com.hbm.machine.oilfracking.*;import java.util.*;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.entity.player.Inventory;
/** The original shared184x190 OilWell GUI, source charge/indicator/tank dimensions and upgrade text. */
public final class FrackingScreen extends LegacyContainerScreen<FrackingMenu> {
 public FrackingScreen(FrackingMenu menu,Inventory inventory,Component title){super(menu,inventory,title,ResourceLocation.parse("hbm:textures/gui/machine/gui_well.png"),184,190);}
 private FrackingEntity machine(){return minecraft!=null&&minecraft.level!=null&&minecraft.level.getBlockEntity(menu.position) instanceof FrackingEntity drill?drill:null;}
 @Override protected void renderLabels(GuiGraphics g,int x,int y){g.drawString(font,title,126-font.width(title)/2,10,4210752,false);g.drawString(font,playerInventoryTitle,12,96,4210752,false);}
 @Override protected void renderBg(GuiGraphics g,float partial,int x,int y){super.renderBg(g,partial,x,y);var m=machine();if(m==null)return;int power=m.getPowerExact().multiply(java.math.BigInteger.valueOf(34)).divide(m.getMaxPowerExact().max(java.math.BigInteger.ONE)).intValue();drawLegacyRegion(g,8,56-power,184,34-power,16,power);if(m.indicator!=0)drawLegacyRegion(g,50,19,184+(m.indicator-1)*14,34,14,14);tank(g,m.tanks[0],76);tank(g,m.tanks[1],112);solution(g,m.tanks[2]);g.blit(ResourceLocation.parse("hbm:textures/gui/gui_utility.png"),leftPos+160,topPos+21,0,32,8,8,256,256);}
 private void solution(GuiGraphics g,FluidTank tank){int height=tank.getFill()*32/tank.getMaxFill();if(height<=0)return;int color=tank.getTankType().getTint();g.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);for(int drawn=0;drawn<height;){int part=Math.min(16,height-drawn);g.blit(tank.getTankType().getTexture(),leftPos+54,topPos+77-drawn-part,0,16-part,6,part,16,16);drawn+=part;}g.setColor(1,1,1,1);}
 private void tank(GuiGraphics g,FluidTank tank,int x){int height=tank.getFill()*52/tank.getMaxFill();if(height<=0)return;int color=tank.getTankType().getTint();g.setColor((color>>16&255)/255F,(color>>8&255)/255F,(color&255)/255F,1);for(int drawn=0;drawn<height;){int piece=Math.min(16,height-drawn);g.blit(tank.getTankType().getTexture(),leftPos+x,topPos+74-drawn-piece,0,16-piece,16,piece,16,16);drawn+=piece;}g.setColor(1,1,1,1);}
 @Override public void render(GuiGraphics g,int x,int y,float partial){super.render(g,x,y,partial);var m=machine();if(m==null)return;for(int i=0;i<2;i++)if(legacyInfoHovered(x,y,76+i*36,22,16,52)){var t=m.tanks[i];var lines=new ArrayList<Component>();lines.add(t.getTankType().displayName());lines.add(Component.literal(t.getFill()+"/"+t.getMaxFill()+"mB"));FluidInfo.append(t.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,x,y);}if(legacyInfoHovered(x,y,54,45,6,32)){var tank=m.tanks[2];var lines=new ArrayList<Component>();lines.add(tank.getTankType().displayName());lines.add(Component.literal(tank.getFill()+"/"+tank.getMaxFill()+"mB"));FluidInfo.append(tank.getTankType(),lines,hasShiftDown());g.renderComponentTooltip(font,lines,x,y);}if(legacyInfoHovered(x,y,8,22,16,34))g.renderTooltip(font,Component.literal(m.getPowerExact()+"/"+m.getMaxPowerExact()+"HE"),x,y);if(legacyInfoHovered(x,y,160,21,8,8))g.renderComponentTooltip(font,List.of(Component.translatable("desc.gui.upgrade"),Component.translatable("desc.gui.upgrade.speed"),Component.translatable("desc.gui.upgrade.power"),Component.translatable("desc.gui.upgrade.afterburner"),Component.translatable("desc.gui.upgrade.overdrive")),x,y);}
}
